---@field Key? aws.machine_learning.TagKey A unique identifier for the tag. Valid characters include Unicode letters, digits, white space, _, ., /, =, +, -, %, and @.
---@field Value? aws.machine_learning.TagValue An optional string, typically used to describe or define the tag. Valid characters include Unicode letters, digits, white space, _, ., /, =, +, -, %, and @.

---@alias aws.machine_learning.TagKey string

---@alias aws.machine_learning.TagKeyList aws.machine_learning.TagKey[]

---@alias aws.machine_learning.TagList aws.machine_learning.Tag[]

---@alias aws.machine_learning.TagValue string

---@alias aws.machine_learning.TaggableResourceType "BatchPrediction"|"DataSource"|"Evaluation"|"MLModel"

---@alias aws.machine_learning.TrainingParameters { [string]: aws.machine_learning.StringType }

---@class aws.machine_learning.UpdateBatchPredictionInput
---@field BatchPredictionId aws.machine_learning.EntityId The ID assigned to the BatchPrediction during creation.
---@field BatchPredictionName aws.machine_learning.EntityName A new user-supplied name or description of the BatchPrediction.

---Represents the output of an UpdateBatchPrediction operation.
---@class aws.machine_learning.UpdateBatchPredictionOutput
---@field BatchPredictionId? aws.machine_learning.EntityId The ID assigned to the BatchPrediction during creation. This value should be identical to the value of the BatchPredictionId in the request.

---@class aws.machine_learning.UpdateDataSourceInput
---@field DataSourceId aws.machine_learning.EntityId The ID assigned to the DataSource during creation.
---@field DataSourceName aws.machine_learning.EntityName A new user-supplied name or description of the DataSource that will replace the current description.

---Represents the output of an UpdateDataSource operation.
---@class aws.machine_learning.UpdateDataSourceOutput
---@field DataSourceId? aws.machine_learning.EntityId The ID assigned to the DataSource during creation. This value should be identical to the value of the DataSourceID in the request.

---@class aws.machine_learning.UpdateEvaluationInput
---@field EvaluationId aws.machine_learning.EntityId The ID assigned to the Evaluation during creation.
---@field EvaluationName aws.machine_learning.EntityName A new user-supplied name or description of the Evaluation that will replace the current content.

---Represents the output of an UpdateEvaluation operation.
---@class aws.machine_learning.UpdateEvaluationOutput
---@field EvaluationId? aws.machine_learning.EntityId The ID assigned to the Evaluation during creation. This value should be identical to the value of the Evaluation in the request.

---@class aws.machine_learning.UpdateMLModelInput
---@field MLModelId aws.machine_learning.EntityId The ID assigned to the MLModel during creation.
---@field MLModelName? aws.machine_learning.EntityName A user-supplied name or description of the MLModel.
---@field ScoreThreshold? aws.machine_learning.ScoreThreshold The ScoreThreshold used in binary classification MLModel that marks the boundary between a positive prediction and a negative prediction.

---Represents the output of an UpdateMLModel operation.
---@class aws.machine_learning.UpdateMLModelOutput
---@field MLModelId? aws.machine_learning.EntityId The ID assigned to the MLModel during creation. This value should be identical to the value of the MLModelID in the request.

---The name of a variable. Currently it's used to specify the name of the target value, label, weight, and tags.
---@alias aws.machine_learning.VariableName string

---The value of a variable. Currently it's used to specify values of the target value, weights, and tag variables and for filtering variable values.
---@alias aws.machine_learning.VariableValue string

---Specifies whether a describe operation should return exhaustive or abbreviated information.
---@alias aws.machine_learning.Verbose boolean

---@alias aws.machine_learning.VipURL string

---@alias aws.machine_learning.floatLabel number

---A second request to use or change an object was not allowed. This can result from retrying a request using a parameter that was not present in the original request.
---@class aws.machine_learning.IdempotentParameterMismatchExceptionError: distilled.Error
---@field tag "IdempotentParameterMismatchException"

---An error on the server occurred when trying to process a request.
---@class aws.machine_learning.InternalServerExceptionError: distilled.Error
---@field tag "InternalServerException"

---An error on the client occurred. Typically, the cause is an invalid input value.
---@class aws.machine_learning.InvalidInputExceptionError: distilled.Error
---@field tag "InvalidInputException"

---@class aws.machine_learning.InvalidTagExceptionError: distilled.Error
---@field tag "InvalidTagException"

---The subscriber exceeded the maximum number of operations. This exception can occur when listing objects such as DataSource.
---@class aws.machine_learning.LimitExceededExceptionError: distilled.Error
---@field tag "LimitExceededException"

---The exception is thrown when a predict request is made to an unmounted MLModel.
---@class aws.machine_learning.PredictorNotMountedExceptionError: distilled.Error
---@field tag "PredictorNotMountedException"

---A specified resource cannot be located.
---@class aws.machine_learning.ResourceNotFoundExceptionError: distilled.Error
---@field tag "ResourceNotFoundException"

---@class aws.machine_learning.TagLimitExceededExceptionError: distilled.Error
---@field tag "TagLimitExceededException"

---@class aws.machine_learning.Options
---@field base_url? string Default https://amazonaws.com
---@field host? table The host seams: transport, sleep, now, exec, random, getenv, epoch
---@field transport? fun(request: table): (table?, distilled.Error?)
---@field sleep? fun(seconds: number)
---@field now? fun(): number
---@field retry? string|table A retry preset or policy fields
---@field deadline_s? number Wall-clock budget for one call, sleeps included
---@field tracing? "off"|"operation"|"debug"|table
---@field validation? "lenient"|"additional"|"strict"
---@field [string] any

---@class aws.machine_learning.Module
local Module = {}

---@param options? aws.machine_learning.Options
---@return aws.machine_learning.Client
function Module.new(options) end

---@class aws.machine_learning.Client
